export function createApp(store: NoteStore, log: (line: string) => void = () => {}) {
  async function route(req: IncomingMessage, res: ServerResponse): Promise<void> {
    const method = req.method ?? "";
    const path = (req.url ?? "").split("?")[0];

    if (path === "/health" && method === "GET") return send(res, 200, { status: "ok" });
    if (path === "/notes" && method === "GET") return send(res, 200, store.list());
    if (path === "/notes" && method === "POST") {
      const { title, body } = parseNoteInput(await readBody(req));
      return send(res, 201, store.create(title, body));
    }
    const match = /^\/notes\/([^/]+)$/.exec(path);
    if (match && method === "GET") {
      let id: string;
      try {
        id = decodeURIComponent(match[1]);
      } catch {
        id = match[1];
      }
      const note = store.get(id);
      return note ? send(res, 200, note) : send(res, 404, { error: "note not found" });
    }
    send(res, 404, { error: "not found" });
  }

  return (req: IncomingMessage, res: ServerResponse): void => {
    const start = performance.now();
    res.on("finish", () => {
      const ms = Math.round(performance.now() - start);
      log(`${req.method} ${(req.url ?? "").split("?")[0]} ${res.statusCode} ${ms}ms`);
    });
    route(req, res).catch((err: unknown) => {
      if (err instanceof HttpError) send(res, err.status, { error: err.message });
      else send(res, 500, { error: "internal server error" });
    });
  };
}
