import type { NoteStore } from "./store.ts";

export const MAX_BODY_BYTES = 1024 * 1024;
const CLOSE_GRACE_MS = 250;

class HttpError extends Error {
  status: number;
  constructor(status: number, message: string) {
    super(message);
    this.status = status;
  }
}

function send(res: ServerResponse, status: number, payload: unknown): void {
  const data = JSON.stringify(payload);
  res.writeHead(status, {
    "Content-Type": "application/json",
    "Content-Length": Buffer.byteLength(data),
  });
  res.end(data);
}

function readBody(req: IncomingMessage): Promise<string> {
  return new Promise((resolve, reject) => {
    const declared = Number(req.headers["content-length"]);
    if (declared > MAX_BODY_BYTES) {
      reject(new HttpError(413, "request body too large"));
      return;
    }
    const chunks: Buffer[] = [];
    let size = 0;
    req.on("data", (chunk: Buffer) => {
      size += chunk.length;
      if (size > MAX_BODY_BYTES) {
        chunks.length = 0;
        req.removeAllListeners("data");
        req.on("data", () => {});
        reject(new HttpError(413, "request body too large"));
        return;
      }
      chunks.push(chunk);
    });
    req.on("end", () => resolve(Buffer.concat(chunks).toString("utf8")));
    req.on("error", reject);
  });
}

function parseNoteInput(raw: string): { title: string; body: string } {
  let data: unknown;
  try {
    data = JSON.parse(raw);
  } catch {
    throw new HttpError(400, "request body must be valid JSON");
  }
  if (typeof data !== "object" || data === null || Array.isArray(data)) {
    throw new HttpError(400, "request body must be a JSON object");
  }
  const { title, body } = data as Record<string, unknown>;
  if (typeof title !== "string" || title.trim() === "") {
    throw new HttpError(400, "title must be a non-empty string");
  }
  if (body !== undefined && typeof body !== "string") {
    throw new HttpError(400, "body must be a string");
  }
  return { title, body: body ?? "" };
}

const NOTE_PATH = /^\/notes\/([^/]+)$/;

function safeDecode(value: string): string {
  try {
    return decodeURIComponent(value);
  } catch {
    return value;
  }
}

export function createApp(store: NoteStore, log: (line: string) => void = () => {}) {
  async function createNote(req: IncomingMessage, res: ServerResponse): Promise<void> {
    const { title, body } = parseNoteInput(await readBody(req));
    send(res, 201, store.create(title, body));
  }

  function getNote(res: ServerResponse, rawId: string): void {
    const note = store.get(safeDecode(rawId));
    if (note) send(res, 200, note);
    else send(res, 404, { error: "note not found" });
  }

